"""RoboPaint public-client trajectory; one permanent episode, no reset."""
import sys, json, time, math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); RUNS=Path('/app/runs')
class Painter:
 def __init__(self):
  self.r=Robot(); self.spec=self.r.spec()
  self.o=self.r.get_obs(cameras=[],video='none')
  self.pose=np.array(self.o.meta['proprio']['now'][7:14]); self.quat=np.array([0.,1.,0.,0.])
  self.i=len(list(RUNS.glob('call_*')))
 def execute(self,rows,dt=.05,cameras=(),note=''):
  rows=np.asarray(rows)
  for start in range(0,len(rows),int(10/dt)):
   a=rows[start:start+int(10/dt)]
   st=self.r.status()
   np.save(OUT/f'command_{self.i:05d}.npy',a)
   try: res=self.r.submit('ee_pose',a,dt=dt,cameras=list(cameras),video='none',note=note)
   except Exception:
    now=self.r.wait_ready(); print('recovered',now,flush=True)
    if now['control_steps']==st['control_steps']: res=self.r.submit('ee_pose',a,dt=dt,cameras=list(cameras),video='none',note=note)
    else:
     res=self.r.get_obs(cameras=list(cameras),video='none')
   self.pose=np.array(res.meta['proprio']['now'][7:14]); self.o=res
   d=RUNS/f'call_{self.i:05d}'; d.mkdir(exist_ok=True)
   (d/'meta.json').write_text(json.dumps(res.meta))
   for c,im in res.last.items(): Image.fromarray(im).save(d/f'{c}.png')
   self.i+=1
   if res.meta.get('plan'): print('plan',res.meta['plan'],flush=True)
  return res
 def path(self,points,speed=.06,hold=.3,cameras=(),note=''):
  rows=[]; cur=self.pose[:3].copy()
  for item in points:
   p=np.array(item[:3]); h=item[3] if len(item)>3 else 0
   n=max(1,int(np.ceil(np.linalg.norm(p-cur)/(speed*.05))))
   for t in np.linspace(0,1,n+1)[1:]: rows.append(np.r_[cur+(p-cur)*t,self.quat])
   for _ in range(int(h/.05)): rows.append(np.r_[p,self.quat])
   cur=p
  for _ in range(int(hold/.05)): rows.append(np.r_[cur,self.quat])
  return self.execute(rows,cameras=cameras,note=note)
if __name__=='__main__':
 p=Painter()
 p.path([[0.,0.,.18],[-.20,.24,.16]],cameras=['canvas_cam','scene_cam','side_cam'],note='clear camera view')
 o=p.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True); o.save('/app/runs/clear')
 print('pose',p.pose, 'status',p.r.status())
