class PrecisionPainter(Painter):
 """Public IK and measured joint feedback only; PD lag compensation."""
 def __init__(self):
  super().__init__(); self.q=np.array(self.o.meta['proprio']['now'][:7]);self.last_command=None
 def execute(self,rows,dt=.05,cameras=(),note=''):
  rows=np.asarray(rows);joints=[]
  for pose in rows:
   ik=self.r.ik({'tip':pose.tolist()},seed=self.q,tol_pos_m=.00002,tol_rot_rad=.0002)
   if not ik['ok']: raise RuntimeError('IK fails '+str(ik))
   self.q=np.array(ik['q']);joints.append(self.q.copy())
  joints=np.array(joints)
  # Motor damping/stiffness is 0.1 s; compensate quasi-static tracking error.
  vel=np.gradient(joints,.05,axis=0) if len(joints)>1 else np.zeros_like(joints)
  command=joints+.10*vel
  for start in range(0,len(command),200):
   a=command[start:start+200];st=self.r.status()
   np.save(OUT/f'command_{self.i:05d}.npy',a)
   (OUT/f'command_{self.i:05d}.json').write_text(json.dumps({'type':'joint_position','dt':dt,'note':note}))
   try: res=self.r.submit('joint_position',a,dt=dt,cameras=list(cameras),video='none',note=note)
   except Exception:
    now=self.r.wait_ready(); print('recovered',now,flush=True)
    if now['control_steps']==st['control_steps']:res=self.r.submit('joint_position',a,dt=dt,cameras=list(cameras),video='none',note=note)
    else:res=self.r.get_obs(cameras=list(cameras),video='none')
   self.pose=np.array(res.meta['proprio']['now'][7:14]);self.o=res
   d=RUNS/f'call_{self.i:05d}';d.mkdir(exist_ok=True);(d/'meta.json').write_text(json.dumps(res.meta))
   for c,im in res.last.items():Image.fromarray(im).save(d/f'{c}.png')
   self.i+=1
   if res.meta.get('clipped'):raise RuntimeError('clipped '+str(res.meta['clipped']))
  self.q=np.array(res.meta['proprio']['now'][:7])
  return res
 def dip(self,color):
  wells=np.array(json.load(open(OUT/'wells_camera.json')));x,y,_=wells[color-1]
  self.path([[self.pose[0],self.pose[1],.055],[x,y,.065],[x,y,.024,.5],[x,y,.065]],speed=.10,note=f'load paint{color:02d}')
